1: import React, { memo, useState } from "react";
2: import { CircleDot, CheckCircle2, AlertTriangle, Clock } from "lucide-react";
3: import { Button } from "@/components/ui/button";
4: import type { GoalProgressMessage } from "../types";
5: import { useT } from "../i18n/I18nProvider";
6: 
7: /** Options the "再续" button passes up — mirrors core's GoalExtension. */
8: export interface GoalExtendOpts {
9:   addTurns?: number;
10:   addStopBlocks?: number;
11:   addTokenBudget?: number;
12:   addTimeBudgetMs?: number;
13: }
14: 
15: /** Default bumps offered by the "再续" button, per limit dimension. */
16: const EXTEND_TURNS = 50;
17: const EXTEND_STOP_BLOCKS = 15;
18: 
19: /**
20:  * Goal-mode progress marker bar — one per judge verdict.
21:  *
22:  *   ◎ 目标未达成 · 第 N 轮 — 还差:{gaps}      (status "not_met")
23:  *   ✓ 目标已达成 · 共 N 轮                     (status "met")
24:  *   ⚠ 目标续跑已达上限(N 轮) · 已停下          (status "exhausted")
25:  *   ⏲ 目标接近续跑上限 · 还剩 N 次   [再续 N 次] (status "approaching_limit")
26:  *
27:  * Counting the "目标未达成" bars tells the user how many rounds the goal ran;
28:  * the trailing "目标已达成 · 共 N 轮" repeats the total. Copy is the judge's
29:  * voice (mirrors goal-stop-hook's 「目标尚未达成 / 还差」). `gaps` is whatever
30:  * the judge already produced — no extra LLM call.
31:  */
32: function GoalProgressViewImpl({
33:   message,
34:   onExtend,
35: }: {
36:   message: GoalProgressMessage;
37:   /** Extend the running goal (TODO 3.1). opts target the nearest ceiling. */
38:   onExtend?: (opts: GoalExtendOpts) => void;
39: }) {
40:   const { t } = useT();
41:   const { status, round, gaps } = message;
42:   // One-shot disable after clicking. Each marker is a fresh component (fresh
43:   // id), and the reducer replaces/prunes this marker once the run advances, so
44:   // no persistent "already extended" state is needed.
45:   const [clicked, setClicked] = useState(false);
46: 
47:   // Approaching a stop ceiling while still running — offer a one-click extend so
48:   // an unattended goal isn't truncated. The button targets whichever limit is
49:   // closest (`nearest`): the stop-block cap (the common case) or maxTurns.
50:   if (status === "approaching_limit") {
51:     const byStopBlocks = message.nearest === "stopBlocks";
52:     const label = byStopBlocks
53:       ? t("msg.goal.extendTimes", { count: EXTEND_STOP_BLOCKS })
54:       : t("msg.goal.extendTurns", { count: EXTEND_TURNS });
55:     const remaining = byStopBlocks ? message.stopBlocksRemaining : message.turnsRemaining;
56:     const headline = byStopBlocks
57:       ? t("msg.goal.approachingStopLimit")
58:       : t("msg.goal.approachingTurnLimit");
59:     const remainingText =
60:       remaining != null
61:         ? byStopBlocks
62:           ? t("msg.goal.remainingTimes", { count: remaining })
63:           : t("msg.goal.remainingTurns", { count: remaining })
64:         : "";
65:     // Always bump turns a little too, so a stop-block extend doesn't later hit
66:     // maxTurns; the streak reset makes the extra harmless.
67:     const opts: GoalExtendOpts = byStopBlocks
68:       ? { addStopBlocks: EXTEND_STOP_BLOCKS, addTurns: EXTEND_TURNS }
69:       : { addTurns: EXTEND_TURNS };
70:     return (
71:       <div className="flex items-center gap-1.5 px-4 py-1 text-xs text-status-warn">
72:         <Clock size={12} className="shrink-0" />
73:         <span className="shrink-0">
74:           {headline}
75:           {remainingText}
76:         </span>
77:         {onExtend &&
78:           (clicked ? (
79:             <span className="text-muted-foreground">{t("msg.goal.extended", { label })}</span>
80:           ) : (
81:             <Button
82:               variant="outline"
83:               size="sm"
84:               className="h-5 px-1.5 py-0 text-[11px]"
85:               onClick={() => {
86:                 setClicked(true);
87:                 onExtend(opts);
88:               }}
89:             >
90:               {label}
91:             </Button>
92:           ))}
93:       </div>
94:     );
95:   }
96: 
97:   if (status === "met") {
98:     return (
99:       <div className="flex items-center gap-1.5 px-4 py-1 text-xs text-status-ok">
100:         <CheckCircle2 size={12} />
101:         <span>{t("msg.goal.metRounds", { count: round })}</span>
102:       </div>
103:     );
104:   }
105: 
106:   if (status === "exhausted") {
107:     return (
108:       <div className="flex items-center gap-1.5 px-4 py-1 text-xs text-status-warn">
109:         <AlertTriangle size={12} />
110:         <span>{t("msg.goal.exhausted", { count: round })}</span>
111:       </div>
112:     );
113:   }
114: 
115:   // not_met — one re-prompt round.
116:   return (
117:     <div className="flex items-center gap-1.5 px-4 py-1 text-xs text-muted-foreground">
118:       <CircleDot size={12} className="shrink-0" />
119:       <span className="shrink-0">{t("msg.goal.notMetRound", { count: round })}</span>
120:       {gaps ? (
121:         <span className="truncate text-muted-foreground/80">{t("msg.goal.gap", { gaps })}</span>
122:       ) : (
123:         <span className="text-muted-foreground/80">{t("msg.goal.keepGoing")}</span>
124:       )}
125:     </div>
126:   );
127: }
128: 
129: // Memoized — see Markdown / ToolCard for the rationale.
130: export const GoalProgressView = memo(GoalProgressViewImpl);
